function printRuntimeResult(reports) {
    console.log(
        '\nBrand performance storefront budget'
    );

    for (const report of reports) {
        if (report.skipped) {
            console.log(
                `- ${report.route}: skipped`
            );
            continue;
        }

        if (!report.medians) {
            console.log(
                `- ${report.route}: ` +
                `failed to measure`
            );
            continue;
        }

        console.log(
            `- ${report.route}: ` +
            `LCP ` +
            `${report.medians.lcpMs.toFixed(
                0
            )} ms; ` +
            `CLS ` +
            `${report.medians.cls.toFixed(
                3
            )}; ` +
            `TBT ` +
            `${report.medians.tbtMs.toFixed(
                0
            )} ms; ` +
            `images ` +
            `${formatBytes(
                report.medians.imageBytes
            )}; ` +
            `image requests ` +
            `${report.medians.imageRequestCount}; ` +
            `resources ` +
            `${report.medians.resourceCount}; ` +
            `global chrome resources ` +
            `${report.medians.globalChromeResourceCount}; ` +
            `global chrome JS ` +
            `${report.medians.globalChromeJsRequestCount}; ` +
            `final ${report.finalUrl || 'unknown'}`
        );

        for (const warning of report.warnings || []) {
            console.warn(
                `  WARNING: ${warning}`
            );
        }
    }
}

async function main() {
    const options = parseArguments(
        process.argv.slice(2)
    );

    const budget = readJson(
        BUDGET_PATH
    );

    validateBudgetShape(budget);

    const staticResult =
        runStaticValidation(budget);

    printStaticResult(staticResult);

    let runtimeReports = [];

    if (options.runtime) {
        runtimeReports =
            await runRuntimeValidation(
                budget,
                options
            );

        printRuntimeResult(
            runtimeReports
        );
    }

    fs.mkdirSync(
        options.reportDir,
        { recursive: true }
    );

    const reportPath = path.join(
        options.reportDir,
        options.runtime
            ? (
                `brand-performance-` +
                `${options.desktop
                    ? 'desktop'
                    : 'mobile'
                }.json`
            )
            : 'brand-performance-static.json'
    );

    fs.writeFileSync(
        reportPath,
        `${JSON.stringify(
            {
                generatedAt:
                    new Date().toISOString(),
                static: staticResult,
                runtime: runtimeReports,
            },
            null,
            2
        )}\n`
    );

    console.log(
        `\nReport: ` +
        `${path.relative(
            ROOT,
            reportPath
        )}`
    );

    const violations = [
        ...staticResult.violations.map(
            (message) =>
                `static: ${message}`
        ),

        ...runtimeReports.flatMap(
            (report) =>
                (
                    report.violations || []
                ).map(
                    (message) =>
                        `${report.route}: ${message}`
                )
        ),
    ];

    if (violations.length) {
        console.error(
            `\nBrand performance validation failed:\n- ` +
            violations.join('\n- ')
        );

        process.exitCode = 1;
        return;
    }

    console.log(
        '\nBrand performance validation passed.'
    );
}

if (require.main === module) {
    main().catch((error) => {
        console.error(
            `Brand performance validation failed: ` +
            `${error.stack || error.message}`
        );

        process.exitCode = 1;
    });
}

